#include <stdio.h>

int main(void)
{
    for (int i = 1; i <= 5; i++) {
        if (i == 3) {
            continue;
        }
        printf("%d", i);
    }
    puts("");
    return 0;
}

#include <stdio.h>

int main(void)
{
    int visits = 0;
    for (int i = 0; i < 3; i++) {
        for (int j = 0; j < 4; j++) {
            visits++;
            break;
        }
    }
    printf("%d\n", visits);
    return 0;
}

